/* @theme deck */
/*
 * エンジニア勉強会 スライドテーマ
 *
 * 方針: 文字は最小限。図で見せて、説明は口で行う。
 *       配色・文字サイズ・コントラストは design-guide のスタイル A（DADS 準拠）に従う。
 */

@import 'default';

:root {
  --blue:      #0031d8;
  --navy:      #000071;
  --blue-50:   #e8f1fe;
  --blue-100:  #d9e6ff;

  --gray-50:   #f2f2f2;
  --gray-100:  #e6e6e6;
  --gray-200:  #cccccc;
  --gray-420:  #949494;
  --gray-536:  #767676;
  --gray-700:  #4d4d4d;
  --ink:       #1a1a1a;

  --green:     #197a4b;
  --red:       #ec0000;

  --sans: 'Hiragino Sans', 'Noto Sans JP', 'Hiragino Kaku Gothic ProN', sans-serif;
  --pad: 64px;
}

section {
  width: 1280px;
  height: 720px;
  padding: 76px var(--pad) 56px;
  background: #ffffff;
  color: var(--ink);
  font-family: var(--sans);
  font-weight: 400;
  font-size: 24px;
  line-height: 1.6;
  letter-spacing: 0.01em;
  display: flex;
  flex-direction: column;
  /* 見出しは全スライドで同じ高さに固定する。中身の量で上下させると、
     めくるたびに視線が見出しを探し直すことになる */
}

section > header {
  position: absolute;
  top: 40px; left: var(--pad); right: var(--pad);
  margin: 0; padding: 0;
  font-size: 18px; font-weight: 700; letter-spacing: 0.02em;
  color: var(--gray-536);
}

section::after {
  position: absolute;
  bottom: 32px; right: var(--pad); left: auto; padding: 0;
  font-size: 18px; color: var(--gray-420);
}

/* 見出し ── 1スライド1メッセージ。短く言い切る */
section h1 {
  font-size: 36px;
  font-weight: 700;
  line-height: 1.4;
  margin: 0 0 24px;
  color: var(--ink);
}

/* 全角の開き括弧は字面の左に約半角ぶんの空きがあるため、そのまま置くと
   見出しだけが小ラベルより右にずれて見える（実測18px／36px時）。ぶら下げて左端をそろえる */
section.kagi h1 { text-indent: -0.5em; }

section p  { margin: 12px 0; }
section ul { margin: 12px 0; padding-left: 1.2em; }
section li { margin: 10px 0; }
section li::marker { color: var(--blue); }
strong { font-weight: 700; }

.note { font-size: 18px; color: var(--gray-536); line-height: 1.5; }

/* 図の置き場。縦の余りを吸収して中央に置く */
/* 中身を縦中央に置くと、見出しとの間に大きな空きができる。
   見出しの直下から始めて、余った余白は下にまとめる */
.fig { flex: 1 1 auto; display: flex; flex-direction: column; justify-content: flex-start; min-height: 0; }
.fig > .tiles,
.fig > .win,
.fig > .flow,
.fig > .branch { flex: none; }
.cap { margin-top: 24px; font-size: 18px; color: var(--gray-536); text-align: center; }

/* ------------------------------------------------------------------
 * レイアウト
 * ---------------------------------------------------------------- */

.row  { display: grid; gap: 24px; align-items: stretch; align-content: center; flex: 1 1 auto; }
.c2   { grid-template-columns: 1fr 1fr; }
.c3   { grid-template-columns: repeat(3, 1fr); }
.c4   { grid-template-columns: repeat(4, 1fr); }
.vs   { grid-template-columns: 1fr 96px 1fr; align-items: center; }

.vs-mark {
  display: flex; align-items: center; justify-content: center;
  font-size: 26px; font-weight: 700; color: var(--gray-420);
}

/* ------------------------------------------------------------------
 * カード
 * ---------------------------------------------------------------- */

.card {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 280px;
  border: 1px solid var(--gray-200);
  border-radius: 12px;
  padding: 40px 28px;
  text-align: center;
}
.card > * { flex: none; }

/* .card は flex コンテナなので、text-align:center はアイコンに効かない。
   固定幅のもの（アイコン・タグ・ロゴ・人型）は align-self で明示的に中央へ寄せる。
   これを忘れると、文字は中央・アイコンだけ左端という崩れ方をする */
.card { align-items: stretch; }
.card > .gi,
.card > .ico,
.card > .tag,
.card > .ai,
.card > .logos,
.card > .figure,
.card > .figure-sm { align-self: center; }
.card .t { font-size: 32px; font-weight: 700; margin: 20px 0 14px; line-height: 1.4; }
.card .d { font-size: 22px; color: var(--gray-700); line-height: 1.6; }

/* 2枚並びは横に余裕があるので、少し大きく見せる */
.c3 > .card .d { font-size: 20px; }
.card.on   { border-color: var(--blue); background: var(--blue-50); }
.card.on .t { color: var(--navy); }
.card.flat { border: none; background: var(--gray-50); }

/* ------------------------------------------------------------------
 * 画面モック
 * ---------------------------------------------------------------- */

.win {
  border: 1px solid var(--gray-200);
  border-radius: 10px;
  overflow: hidden;
  background: #ffffff;
  box-shadow: 0 4px 16px 3px rgba(0,0,0,0.1), 0 1px 6px 0 rgba(0,0,0,0.3);
}
.win .bar {
  display: flex; align-items: center; gap: 8px;
  height: 34px; padding: 0 14px;
  background: var(--gray-50); border-bottom: 1px solid var(--gray-200);
}
.win .bar i { width: 10px; height: 10px; border-radius: 50%; background: var(--gray-200); }
.win .bar b { margin-left: 10px; font-size: 16px; font-weight: 400; color: var(--gray-536); }
.win .bar > .ico { width: 18px; height: 18px; margin: 0 0 0 10px; }
.win .bar > .ico + b { margin-left: 0; }
.win .body { display: grid; height: 232px; }
.win.two   .body { grid-template-columns: 34% 1fr; }
.win.three .body { grid-template-columns: 30% 1fr 26%; }
.win .p { padding: 14px 16px; border-right: 1px solid var(--gray-100); overflow: hidden; }
.win .p:last-child { border-right: none; }
.win .p.dark { background: var(--ink); }
.win .h { font-size: 14px; font-weight: 700; letter-spacing: 0.02em; color: var(--gray-536); margin-bottom: 10px; }

/* モックの中の行 */
.ln { height: 10px; border-radius: 2px; background: var(--gray-100); margin: 9px 0; }
.ln.s  { width: 55%; }
.ln.m  { width: 75%; }
.ln.l  { width: 92%; }
.ln.b  { background: var(--blue-100); }
.ln.k  { background: var(--blue); }
.ln.d  { background: var(--gray-700); }
.ln.dg { background: var(--green); }

.stat { display: flex; align-items: center; gap: 10px; margin: 12px 0; font-size: 16px; }
.stat i { width: 12px; height: 12px; border-radius: 50%; flex: none; }
.stat i.run  { background: var(--blue); }
.stat i.wait { background: var(--red); }
.stat i.done { background: var(--gray-200); }

/* ------------------------------------------------------------------
 * 人型（AI に見立てる）
 * ---------------------------------------------------------------- */

.ai { display: flex; flex-direction: column; align-items: center; gap: 12px; }
.ai .glyph { width: 96px; height: 96px; background-repeat: no-repeat; background-position: center; background-size: contain; }
.ai .role  { font-size: 22px; font-weight: 700; line-height: 1.4; text-align: center; }
.ai .sub   { font-size: 18px; color: var(--gray-536); line-height: 1.4; text-align: center; }
.ai.sm .glyph { width: 64px; height: 64px; }

.proj { display: flex; flex-direction: column; align-items: center; gap: 16px; }
/* box-sizing を指定しないと width:100% に padding と border が足され、
   枠が列からはみ出して行全体が左右の余白（64px）を突き破る。実測で片側17px出ていた */
.proj .box {
  width: 100%; box-sizing: border-box;
  border: 1px solid var(--gray-200); border-radius: 10px;
  padding: 18px 16px; text-align: center; font-size: 20px; font-weight: 700;
}
.proj .box.on { border-color: var(--blue); background: var(--blue-50); color: var(--navy); }

/* 枠の中の要素は縦横とも中央にそろえる（全部品共通の約束） */
.proj .box,
.flow .step,
.leaf,
.branch .root {
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
}

/* 囲み（ラベル付き） */
.group {
  position: relative;
  border: 2px solid var(--gray-200);
  border-radius: 14px;
  padding: 36px 28px 28px;
}
.group > .gl {
  position: absolute; top: -14px; left: 24px;
  background: #ffffff; padding: 0 14px;
  font-size: 18px; font-weight: 700; letter-spacing: 0.02em;
  color: var(--gray-536);
}
.group.on { border-color: var(--blue); }
.group.on > .gl { color: var(--blue); }


/* 2段組み。1枚に強み3つ＋弱み2つのように積むとき。
   段ごとに縦を分け合うので、カードの min-height は効かせない */
.rows { display: flex; flex-direction: column; gap: 20px; flex: 1 1 auto; min-height: 0; }
.rows > .row { flex: 1 1 0; align-content: stretch; margin: 0; }
/* 枠の中の要素は必ず縦横とも中央。段組みでも例外にしない
   （上揃えにするとカードの下に空白が溜まる） */
.rows .card { min-height: 0; padding: 22px 20px; justify-content: center; }
.rows .card .t { font-size: 26px; margin: 10px 0 8px; }
.rows .card .d { font-size: 20px; line-height: 1.5; }
.rows .card .tag { margin-bottom: 8px; }

/* 見出しの右にロゴを添えるとき */
.head { display: flex; align-items: center; justify-content: space-between; gap: 24px; margin: 0 0 20px; }
.head h1 { margin: 0; }
.head .tiles { gap: 16px; }
.head .tile { width: 84px; height: 84px; border-radius: 16px; }
.head .tile .ico { width: 50px; height: 50px; }
.head .tile-name { display: none; }

/* 流れ */
.flow { display: grid; grid-auto-flow: column; align-items: center; justify-content: center; gap: 20px; }
.flow .step {
  border: 1px solid var(--gray-200); border-radius: 10px;
  padding: 22px 26px; font-size: 22px; font-weight: 700; text-align: center;
}
.flow .step.on { border-color: var(--blue); background: var(--blue-50); color: var(--navy); }
.flow .arw { font-size: 28px; color: var(--gray-420); }

/* 良い / 悪い */
.tag {
  display: inline-block; border-radius: 6px;
  font-size: 18px; font-weight: 700; letter-spacing: 0.02em;
  padding: 5px 14px; margin-bottom: 14px;
}
.tag.good { background: var(--green); color: #ffffff; }
.tag.bad  { background: var(--red);   color: #ffffff; }
.tag.plain{ background: var(--gray-100); color: var(--gray-700); }

/* 内容を表すアイコン */
.gi {
  display: inline-block; width: 56px; height: 56px;
  background-repeat: no-repeat; background-position: center; background-size: contain;
}
.gi.lg { width: 88px; height: 88px; }

/* ロゴ */
.ico { display: inline-block; width: 1.1em; height: 1.1em; vertical-align: -0.2em; margin-right: 0.2em;
       background-repeat: no-repeat; background-position: center; background-size: contain; }
.ico-lg { width: 56px; height: 56px; vertical-align: middle; margin: 0; }
.logos  { display: flex; align-items: center; justify-content: center; gap: 24px; margin-top: 8px; }
/* 各社でアイコンの地の有無が違う（cmuxは透過・herdrは不透明）ので、
   カード見出しに並べるときは同じ大きさの白タイルに載せて視覚の重さを揃える */
.logos.chips .ico-lg {
  width: 44px; height: 44px; padding: 8px; box-sizing: content-box;
  /* background ショートハンドだと .ico の background-image ごと消えてアイコンが真っ白になる */
  border: 1px solid var(--gray-200); border-radius: 12px; background-color: #ffffff;
}

/* ロゴを大きく並べるとき。各社でアイコンの地の有無が違う（herdr は不透明）ので、
   同じ大きさのタイルに載せて見た目を揃える */
.tiles { display: flex; align-items: center; justify-content: center; gap: 28px; }
.tile { width: 168px; height: 168px; }
.tile .ico { width: 100px; height: 100px; }
.tile {
  width: 128px; height: 128px;
  display: flex; align-items: center; justify-content: center;
  border: 1px solid var(--gray-200); border-radius: 24px;
  background: #ffffff;
}
.tile .ico { width: 76px; height: 76px; margin: 0; }
.tile-name { margin-top: 12px; font-size: 18px; color: var(--gray-536); text-align: center; }
.tile-set  { display: flex; flex-direction: column; align-items: center; }

/* ------------------------------------------------------------------
 * 定義・比較・依存関係
 * ---------------------------------------------------------------- */

.layer-stack { display: grid; gap: 16px; }
.layer {
  min-height: 112px;
  display: grid; grid-template-columns: 52px 1fr auto; align-items: center; gap: 22px;
  border: 1px solid var(--gray-200); border-radius: 12px; padding: 20px 28px;
}
.layer.on { border-color: var(--blue); background: var(--blue-50); }
.layer-no {
  width: 44px; height: 44px; display: flex; align-items: center; justify-content: center;
  border-radius: 50%; background: var(--blue); color: #ffffff; font-size: 22px; font-weight: 700;
}
.layer b { display: block; font-size: 28px; line-height: 1.3; }
.layer small { display: block; margin-top: 5px; font-size: 20px; color: var(--gray-700); }
.layer .logos { margin: 0; }
.tool-words { display: flex; align-items: center; justify-content: center; gap: 10px; flex-wrap: wrap; }
.tool-words span {
  border: 1px solid var(--gray-200); border-radius: 7px; padding: 5px 12px;
  background: #ffffff; color: var(--ink); font-size: 18px; font-weight: 700;
}

.scene-grid { display: grid; grid-template-columns: 1.05fr 1fr; gap: 44px; align-items: center; }
.terminal-screen {
  /* 内容が少ないと黒地が余り、多いとキャプションが下端をはみ出す。
     2枚（②③）が並ぶので枠の大きさは揃えたいが、余らせすぎない値にする */
  min-height: 248px; overflow: hidden; border-radius: 12px; background: var(--ink);
  box-shadow: 0 4px 16px 3px rgba(0,0,0,0.1), 0 1px 6px 0 rgba(0,0,0,0.3);
  display: flex; flex-direction: column; padding: 62px 34px 28px; position: relative;
}
.terminal-bar {
  position: absolute; top: 0; left: 0; right: 0; height: 40px; padding: 0 18px;
  display: flex; align-items: center; background: var(--gray-50); color: var(--gray-700);
  font-size: 16px; font-family: var(--sans);
}
.terminal-screen code { display: block; color: #ffffff; background: transparent; font-size: 22px; line-height: 1.7; }
.terminal-screen code.output { color: #9de2b9; margin: 0 0 16px 18px; }
.terminal-screen .prompt { color: #7ea6ff; font-weight: 700; }
/* そのまま貼れる指示文を見せる枠。項目名だけ色を変えて、型が読み取れるようにする。
   間隔は全角スペースでなく margin で作る（表記ルール） */
.paste code { line-height: 1.9; }
/* 2行目以降は同じ入力の続き。プロンプト記号を繰り返すと4回打ったように見える */
.paste code.cont { padding-left: 1.55em; }
.paste .k {
  display: inline-block; min-width: 8em; margin-right: 12px;
  color: #7ee3b0; font-weight: 700;
}
.editor-scene .body { height: 330px; }
.numbered { display: grid; gap: 16px; }
.numbered > div { border-left: 5px solid var(--blue); padding: 12px 0 12px 20px; }
.numbered b { display: block; font-size: 26px; line-height: 1.3; }
.numbered span { display: block; margin-top: 5px; color: var(--gray-700); font-size: 20px; line-height: 1.5; }

.pair { display: grid; grid-template-columns: 1fr 74px 1fr; gap: 24px; align-items: center; }
.pair-side {
  min-height: 260px; border: 1px solid var(--gray-200); border-radius: 12px; padding: 34px 30px;
  display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center;
}
.pair-side.on { border-color: var(--blue); background: var(--blue-50); }
.pair-side .logos, .pair-side .tool-words { margin-bottom: 24px; }
.pair-side b { font-size: 28px; line-height: 1.4; }
.pair-side > span { margin-top: 12px; color: var(--gray-700); font-size: 20px; line-height: 1.5; }
.pair-link { text-align: center; font-size: 36px; color: var(--gray-420); }
.rule {
  margin-top: 28px; border-left: 8px solid var(--blue); background: var(--blue-50);
  padding: 18px 24px; color: var(--navy); font-size: 24px; font-weight: 700; text-align: center;
}

.compare { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 20px; line-height: 1.45; }
.compare th, .compare td { border-bottom: 1px solid var(--gray-200); padding: 20px 18px; vertical-align: middle; }
.compare thead th { background: var(--gray-50); color: var(--gray-700); font-size: 18px; font-weight: 700; }
.compare tbody th { width: 17%; text-align: left; font-size: 22px; }
.compare tbody td { color: var(--gray-700); }
.compare tr.on th, .compare tr.on td { background: var(--blue-50); }
.terminal-tools { font-size: 18px; }
.terminal-tools th, .terminal-tools td { padding-top: 16px; padding-bottom: 16px; }
.terminal-tools tbody th { width: 14%; }
.failures { font-size: 20px; }
.failures thead th:first-child { width: 34%; }
.failures tbody th { width: auto; font-size: 20px; }

.attention-scale { display: grid; grid-template-columns: 1fr 170px 1fr; gap: 12px; align-items: center; }
.attention-side {
  min-height: 270px; display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; border: 1px solid var(--gray-200); border-radius: 12px; padding: 30px;
}
.attention-side.on { border-color: var(--blue); background: var(--blue-50); }
.attention-side .logos, .attention-side .tool-words { margin-bottom: 22px; }
.attention-side b { font-size: 28px; }
.attention-side > span { margin-top: 10px; color: var(--gray-700); font-size: 20px; }
.attention-line { height: 6px; background: linear-gradient(90deg, var(--gray-200), var(--blue)); position: relative; }
.attention-line i { position: absolute; top: -8px; left: calc(50% - 11px); width: 22px; height: 22px; border-radius: 50%; background: var(--blue); }

.ai-row { flex: none; gap: 12px; margin-bottom: 18px; }
/* すき間が狭いと3つの枠が1本の表に見える。分かれていることを見せる */
.project-row { flex: none; gap: 24px; margin-bottom: 28px; }
.project-row .ai .glyph { width: 72px; height: 72px; }
.compact-flow { gap: 12px; }
.compact-flow .step { padding: 16px 18px; font-size: 20px; }
.state-row { flex: none; }
.state-row .card { min-height: 250px; }
.status-dot { width: 26px; height: 26px; border-radius: 50%; align-self: center; margin-bottom: 6px; }
.status-dot.run { background: var(--blue); }
.status-dot.wait { background: var(--red); }
.status-dot.done { background: var(--gray-420); }

.contract-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 14px; }
.contract-grid > div {
  min-height: 220px; border-top: 8px solid var(--blue); background: var(--gray-50);
  padding: 26px 18px; display: flex; flex-direction: column; justify-content: center; text-align: center;
}
.contract-grid b { font-size: 22px; color: var(--navy); }
.contract-grid span { margin-top: 16px; color: var(--gray-700); font-size: 18px; line-height: 1.5; }

.dependency { display: flex; flex-direction: column; align-items: center; }
.dep-row { width: 100%; display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.dep-node {
  min-height: 110px; border: 1px solid var(--gray-200); border-radius: 10px; padding: 20px;
  display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center;
}
.dep-node.on { border-color: var(--blue); background: var(--blue-50); color: var(--navy); }
.dep-node.root { width: 48%; min-height: 80px; font-size: 24px; font-weight: 700; }
.dep-node b { font-size: 24px; }
.dep-node span { margin-top: 6px; color: var(--gray-700); font-size: 18px; }
.dep-arrow { height: 48px; color: var(--gray-420); font-size: 32px; line-height: 48px; }

.question-strip { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; margin-bottom: 22px; }
.question-strip > div {
  min-height: 104px; display: flex; align-items: center; gap: 14px; background: var(--gray-50);
  padding: 18px; font-size: 18px; line-height: 1.4;
}
.question-strip span {
  width: 36px; height: 36px; border-radius: 50%; background: var(--blue); color: #ffffff;
  display: flex; align-items: center; justify-content: center; flex: none; font-weight: 700;
}
.parallel-examples { flex: none; }
.parallel-examples .card { min-height: 220px; padding: 26px; }

.worktree-grid { display: grid; grid-template-columns: 1.2fr repeat(3, 1fr); gap: 16px; margin-bottom: 24px; }
.workspace {
  min-height: 126px; border: 1px solid var(--gray-200); border-radius: 10px; padding: 20px;
  display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center;
}
.workspace.local { border-color: var(--blue); background: var(--blue-50); }
.workspace b { font-size: 24px; }
.workspace span { margin-top: 8px; color: var(--gray-700); font-size: 18px; }
.mini-cards { flex: none; }
.mini-cards .card { min-height: 160px; padding: 20px; }
.mini-cards .card .t { margin: 0 0 8px; font-size: 22px; }
.mini-cards .card .d { font-size: 18px; line-height: 1.45; }

.ticket { border: 1px solid var(--gray-200); border-radius: 12px; overflow: hidden; }
.ticket > div { display: grid; grid-template-columns: 190px 1fr; min-height: 64px; border-bottom: 1px solid var(--gray-200); }
.ticket > div:last-child { border-bottom: none; }
.ticket b { display: flex; align-items: center; padding: 12px 24px; background: var(--blue-50); color: var(--navy); font-size: 20px; }
.ticket span { display: flex; align-items: center; padding: 12px 24px; font-size: 20px; }
.ticket code { background: var(--gray-50); border-radius: 5px; padding: 3px 8px; color: var(--ink); }

.role-flow { display: grid; grid-template-columns: 220px 1fr 220px; gap: 20px; align-items: center; }
.role-lead {
  min-height: 260px; border: 1px solid var(--gray-200); border-radius: 12px; padding: 24px;
  display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center;
}
.role-lead.on { border-color: var(--blue); background: var(--blue-50); }
.role-lead b { font-size: 26px; }
.role-lead span { margin-top: 12px; color: var(--gray-700); font-size: 18px; }
.role-workers { display: grid; gap: 12px; }
.role-workers > div { display: grid; grid-template-columns: 130px 1fr; border: 1px solid var(--gray-200); border-radius: 8px; overflow: hidden; }
.role-workers b { padding: 16px; background: var(--gray-50); font-size: 20px; }
.role-workers span { padding: 16px; color: var(--gray-700); font-size: 18px; }
.integration-flow { gap: 10px; }
.integration-flow .step { padding: 18px 14px; font-size: 18px; min-width: 152px; }
.integration-flow .arw { font-size: 22px; }

/* ------------------------------------------------------------------
 * 学生向けの4担当フロー
 * 後半は表やカードを連続させず、人型・紙・一本の流れで見せる。
 * ---------------------------------------------------------------- */

.plan-layout { display: grid; grid-template-columns: 1.3fr 0.7fr; gap: 64px; align-items: center; }
.plan-paper {
  border-left: 10px solid var(--blue); background: var(--gray-50);
  padding: 26px 32px; box-shadow: 0 4px 16px rgba(0,0,0,0.08);
}
.plan-paper-title { font-size: 28px; font-weight: 700; color: var(--navy); margin-bottom: 14px; }
.plan-paper > div:not(.plan-paper-title) {
  display: grid; grid-template-columns: 110px 1fr; gap: 18px;
  padding: 12px 0; border-top: 1px solid var(--gray-200);
}
.plan-paper b { font-size: 20px; }
.plan-paper span { font-size: 20px; color: var(--gray-700); }
.plan-voice { text-align: center; }
.plan-voice p { margin: 18px 0 0; font-size: 32px; font-weight: 700; line-height: 1.5; color: var(--navy); }

.role-cast { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; align-items: stretch; }
.role-person {
  position: relative; min-height: 300px; padding: 28px 18px 24px;
  border-bottom: 6px solid var(--blue);
  display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center;
}
.role-person.review { background: var(--blue-50); border-bottom-color: var(--green); border-radius: 12px 12px 0 0; }
.role-person .ai .glyph { width: 82px; height: 82px; }
.role-person b { margin-top: 18px; font-size: 24px; line-height: 1.35; }
.role-person > span:not(.role-number) { margin-top: 8px; font-size: 18px; color: var(--gray-700); }
.role-number {
  position: absolute; top: 16px; left: 16px; width: 38px; height: 38px;
  border-radius: 50%; background: var(--blue); color: #ffffff;
  display: flex; align-items: center; justify-content: center; font-size: 18px; font-weight: 700;
}
.role-person.review .role-number { background: var(--green); }

.parallel-board { display: grid; grid-template-columns: 1.4fr 104px 0.9fr; gap: 16px; align-items: center; }
.parallel-left { display: flex; flex-direction: column; align-items: center; }
.parallel-source {
  min-width: 290px; padding: 16px 28px; text-align: center;
  background: var(--blue-50); color: var(--navy); border: 1px solid var(--blue);
  font-size: 22px; font-weight: 700;
}
.parallel-down { height: 42px; color: var(--gray-420); font-size: 28px; line-height: 42px; }
.parallel-runs { width: 100%; display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.parallel-runs > div { min-height: 132px; border-bottom: 6px solid var(--blue); padding: 18px 12px; text-align: center; }
.parallel-runs span {
  width: 32px; height: 32px; margin: 0 auto 8px; border-radius: 50%;
  background: var(--blue); color: #ffffff; display: flex; align-items: center; justify-content: center;
  font-size: 17px; font-weight: 700;
}
.parallel-runs b { display: block; font-size: 20px; line-height: 1.35; }
.parallel-runs small { display: block; margin-top: 6px; color: var(--gray-700); font-size: 17px; }
.parallel-next { display: flex; flex-direction: column; align-items: center; font-size: 36px; line-height: 1; color: var(--gray-420); }
.parallel-next small { margin-top: 8px; font-size: 16px; line-height: 1.35; text-align: center; }
.parallel-review {
  min-height: 0; background: var(--blue-50); border-bottom: 6px solid var(--green);
  display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center;
  /* この枠が板の高さを決める。太らせると下の帯がスライド下端をはみ出す */
  padding: 12px 16px;
}
.parallel-review .ai .glyph { width: 44px; height: 44px; }
.parallel-review b { margin-top: 8px; font-size: 20px; }
.parallel-review span { margin-top: 4px; font-size: 16px; color: var(--gray-700); }

.outcome-list { display: grid; gap: 16px; }
.outcome-list > div {
  min-height: 104px; display: grid; grid-template-columns: 48px 230px 1fr 260px;
  gap: 18px; align-items: center; border-bottom: 1px solid var(--gray-200); padding: 8px 18px;
}
.outcome-no {
  width: 38px; height: 38px; border-radius: 50%; background: var(--blue); color: #ffffff;
  display: flex; align-items: center; justify-content: center; font-size: 18px; font-weight: 700;
}
.outcome-list b { font-size: 24px; }
.outcome-list p { margin: 0; font-size: 22px; }
.outcome-list small { font-size: 18px; color: var(--gray-700); }

.prompt-layout { display: grid; grid-template-columns: 220px 90px 1fr; gap: 24px; align-items: center; }
.prompt-person { text-align: center; }
.prompt-person .ai .glyph { width: 100px; height: 100px; }
.prompt-person b { display: block; margin-top: 18px; font-size: 26px; }
.prompt-arrow { text-align: center; font-size: 36px; color: var(--gray-420); }
.prompt-paper {
  border-left: 10px solid var(--blue); background: var(--gray-50);
  padding: 18px 30px; box-shadow: 0 4px 16px rgba(0,0,0,0.08);
}
.prompt-paper > div {
  min-height: 64px; display: grid; grid-template-columns: 180px 1fr;
  gap: 20px; align-items: center; border-bottom: 1px solid var(--gray-200);
}
.prompt-paper > div:last-child { border-bottom: none; }
.prompt-paper b { font-size: 20px; color: var(--navy); }
.prompt-paper span { font-size: 20px; }

/* 事故の実例。時刻・担当・起きたことの3列で、順に起きたことが読めるようにする */
.incident { display: grid; gap: 10px; }
.incident > div {
  display: grid; grid-template-columns: 108px 240px 1fr; gap: 20px; align-items: center;
  box-sizing: border-box; padding: 14px 20px;
  border-left: 6px solid var(--gray-200); background: var(--gray-50);
}
.incident > div.bad { border-left-color: var(--red); background: #fff5f5; }
.incident .w { font-size: 20px; font-weight: 700; color: var(--gray-536); }
.incident b  { font-size: 22px; }
.incident .d { font-size: 20px; color: var(--gray-700); }
.incident > div.bad .d { color: var(--ink); }

.conflict-layout { grid-template-columns: 1.15fr 0.85fr; }
.conflict-scene { display: grid; grid-template-columns: 1fr 1.15fr 1fr; gap: 12px; align-items: center; }
.conflict-person { text-align: center; }
.conflict-person .ai .glyph { width: 74px; height: 74px; }
.conflict-person b { display: block; margin-top: 12px; font-size: 20px; line-height: 1.35; }
.conflict-file {
  position: relative; min-height: 170px; border: 2px solid var(--red); background: #fff5f5;
  display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center;
  padding: 22px 12px;
}
.conflict-file::before, .conflict-file::after {
  content: "→"; position: absolute; top: 60px; color: var(--red); font-size: 32px; font-weight: 700;
}
.conflict-file::before { left: -44px; }
.conflict-file::after { right: -44px; transform: rotate(180deg); }
/* ×は枠の上辺にまたがる。地を白で抜かないと赤い枠線が×の後ろを素通りして汚れる */
.conflict-file strong {
  position: absolute; top: -28px; font-size: 45px; color: var(--red); line-height: 1;
  background: #ffffff; padding: 0 12px;
}
.conflict-file b { font-size: 22px; }
.conflict-file span { margin-top: 8px; font-size: 16px; color: var(--gray-700); }

.review-merge { display: grid; grid-template-columns: 1fr 58px 0.9fr 58px 1.05fr; gap: 16px; align-items: center; }
.review-inputs { display: grid; gap: 18px; }
.review-inputs > div {
  min-height: 72px; display: grid; grid-template-columns: 20px 1fr; align-items: center;
  border-bottom: 1px solid var(--gray-200); padding: 8px 12px;
}
.review-inputs b { font-size: 21px; }
.review-inputs small { grid-column: 2; font-size: 17px; color: var(--gray-700); }
.review-dot { width: 14px; height: 14px; border-radius: 50%; display: block; grid-row: 1 / span 2; }
.review-dot.blue { background: var(--blue); }
.review-dot.navy { background: var(--navy); }
.review-dot.gray { background: var(--gray-420); }
.review-arrow { text-align: center; font-size: 36px; color: var(--gray-420); }
.review-person {
  min-height: 250px; background: var(--blue-50); border-bottom: 6px solid var(--green);
  display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center;
  padding: 24px 18px;
}
.review-person .ai .glyph { width: 84px; height: 84px; }
.review-person b { margin-top: 14px; font-size: 24px; }
.review-person span { margin-top: 8px; font-size: 18px; color: var(--gray-700); }
.review-checks { display: grid; gap: 16px; }
.review-checks > div {
  border-left: 6px solid var(--blue); padding: 16px 12px 16px 18px;
  font-size: 20px; font-weight: 700;
}
.review-checks > div::before { content: "✓"; color: var(--green); margin-right: 10px; }

.mistake-list { display: grid; gap: 16px; }
.mistake-list > div {
  min-height: 104px; display: grid; grid-template-columns: 46px 1fr 60px 1fr;
  gap: 18px; align-items: center; border-bottom: 1px solid var(--gray-200); padding: 8px 20px;
}
.mistake-list span {
  width: 38px; height: 38px; border-radius: 50%; background: var(--red); color: #ffffff;
  display: flex; align-items: center; justify-content: center; font-size: 18px; font-weight: 700;
}
.mistake-list b { font-size: 23px; }
.mistake-list i { font-size: 30px; font-style: normal; color: var(--gray-420); text-align: center; }
.mistake-list strong { font-size: 23px; color: var(--navy); }

.closing-path {
  display: grid; grid-template-columns: 1fr 70px 1fr 70px 1fr; gap: 18px; align-items: center;
}
/* 3列とも同じ「面＋下線」にする。強調列だけに面を付けると、他の2列が宙に浮いて見える */
.closing-path > div {
  min-height: 300px; display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; background: var(--gray-50); border-bottom: 6px solid var(--gray-200); padding: 28px 20px;
}
.closing-path > div.on { background: var(--blue-50); border-bottom-color: var(--blue); }
.closing-path b { margin-top: 22px; font-size: 26px; line-height: 1.4; }  /* 28px だと「人が動かして確認する」が折り返す */
.closing-path small { margin-top: 10px; font-size: 18px; color: var(--gray-700); }
.closing-arrow { text-align: center; font-size: 36px; color: var(--gray-420); }

/* ターミナル3製品の詳細。比較しやすい骨格を保ち、中央のロゴ位置だけ交互に振る。 */
/* 右カラムを 1fr にすると残り幅いっぱいに広がり、中身は左端から並ぶので
   右側だけ空いて左寄りに見える。列を中身なりの幅にして、2列ごと中央へ置く */
.terminal-profile {
  display: grid; grid-template-columns: 350px auto; gap: 58px;
  align-items: center; justify-content: center;
}
.terminal-profile.reverse { grid-template-columns: auto 350px; }
.terminal-profile.reverse .terminal-brand { order: 2; }
.terminal-profile.reverse .terminal-points { order: 1; }
section:has(.terminal-profile) {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  align-content: start;
  /* 列を明示しないと中身の幅に縮み、継承された justify-content:center で
     グリッド全体が中央へ寄る（見出しだけ約137px 右へずれていた） */
  grid-template-columns: minmax(0, 1fr);
  justify-content: stretch;
  padding-top: 76px;
}
section:has(.terminal-profile) h1 {
  margin-bottom: 32px;
  justify-self: stretch;
  text-align: left;
}
.terminal-brand {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center;
}
.terminal-logo {
  display: block; width: 174px; height: 174px; margin-bottom: 20px;
  background-repeat: no-repeat; background-position: center; background-size: contain;
}
.terminal-brand > b { font-size: 38px; line-height: 1.2; }
.terminal-kind { margin-top: 6px; font-size: 19px; color: var(--gray-536); }
.terminal-fit {
  width: 100%; margin-top: 24px; padding-top: 18px; border-top: 1px solid var(--gray-200);
  font-size: 18px; line-height: 1.45;
}
.terminal-fit b { display: block; margin-bottom: 5px; color: var(--navy); font-size: 18px; }
.terminal-fit span { display: block; color: var(--gray-700); }
.terminal-points { display: grid; gap: 28px; }
.terminal-point { padding: 4px 0 4px 28px; border-left: 8px solid var(--gray-200); }
.terminal-point.strength { border-left-color: var(--green); }
.terminal-point.weakness { border-left-color: var(--red); }
.terminal-point h2 { margin: 0 0 12px; font-size: 25px; line-height: 1.3; }
.terminal-point.strength h2 { color: var(--green); }
.terminal-point.weakness h2 { color: var(--red); }
.terminal-point ul { margin: 0; padding: 0; list-style: none; }
.terminal-point li { position: relative; margin: 8px 0; padding-left: 28px; font-size: 21px; line-height: 1.45; }
.terminal-point li::before {
  position: absolute; left: 0; top: 0; font-weight: 700;
}
.terminal-point.strength li::before { content: "✓"; color: var(--green); }
.terminal-point.weakness li::before { content: "−"; color: var(--red); }

/* 章ラベルは全ページ同じ位置に出す。
   ページ番号を出していないので、これが唯一の現在地表示になる（design-guide の共通原則）。
   以前はレイアウトごとに display:none で消していたが、出る枚と出ない枚が混在していた。 */

/* ------------------------------------------------------------------
 * スライド種別
 * ---------------------------------------------------------------- */

section.title {
  background: var(--navy); color: #ffffff; justify-content: center;
}
section.title > header, section.title::after { display: none; }
section.title h1 { font-size: 48px; color: #ffffff; margin: 0 0 28px; }
section.title p  { font-size: 22px; color: rgba(255,255,255,0.8); margin: 0; line-height: 1.75; }

section.chapter {
  background: var(--blue-50); justify-content: center;
}
section.chapter h1 { font-size: 45px; color: var(--navy); margin: 0 0 16px; }
section.chapter p  { font-size: 24px; color: var(--gray-700); margin: 0; }
section.chapter .n {
  font-size: 20px; font-weight: 700; letter-spacing: 0.02em;
  color: var(--blue); margin-bottom: 20px;
}

section.big { justify-content: center; }
section.big h1 { font-size: 45px; line-height: 1.4; margin: 0; }
section.big p  { font-size: 24px; color: var(--gray-700); margin: 24px 0 0; max-width: 26em; }

section > *:last-child { margin-bottom: 0; }
section > .note:last-child { margin-top: 24px; padding-top: 0; }

