.parallel-review .review-checks { margin-top: 8px; text-align: left; }
.parallel-review .review-checks > div {
  position: relative; padding-left: 24px; margin: 5px 0;
  font-size: 20px; line-height: 1.35; color: var(--ink);
}
.parallel-review .review-checks > div::before {
  content: "✓"; position: absolute; left: 0; color: var(--green); font-weight: 700;
}
